 x,y=q['atlas_x'],q['atlas_y'];xx=i%5*200;yy=i//5*130;c=im.crop((x-4,y-4,x+5,y+5)).resize((90,90),Image.Resampling.NEAREST);out.paste(c,(xx,yy+30),c);d.text((xx,yy),f"r{q['row']} c{q['frame']} {q['x']},{q['y']}",fill='white');d.rectangle((xx+40,yy+70,xx+49,yy+79),outline='magenta')
